&lt;span id=&#34;cb7-20&#34;&gt;&lt;a href=&#34;#cb7-20&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            &lt;span class=&#34;cf&#34;&gt;return&lt;/span&gt; node&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;f&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; g &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; q&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;g&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt;&lt;/span&gt;
